import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Login.css";

export default function LoginScreen({ onSelect, onProbarModelo, navigate: navProp }) {
  const [visible, setVisible] = useState(false);
  const navigate = navProp || useNavigate();

  // Cuando se monta, hacemos un fade‐in tras 100 ms (simula el fin del splash)
  useEffect(() => {
    const timer = setTimeout(() => setVisible(true), 100);
    return () => clearTimeout(timer);
  }, []);

  // Adaptar los handlers para usar navigate
  const handleUser = () => {
    if (onSelect) onSelect("user", navigate);
    else navigate("/dashboard");
  };
  const handleAdmin = () => {
    if (onSelect) onSelect("admin", navigate);
    else navigate("/adminLogin");
  };
  const handleProbarModelo = () => {
    if (onProbarModelo) onProbarModelo(navigate);
    else navigate("/probarModelo");
  };

  return (
    <div
      className={`login-screen-container ${
        visible ? "fade-in" : "fade-out"
      }`}
    >
      <div className="login-screen-left">
        <div className="welcome-box">
          <h1>CPATBUS</h1>
          <p>BIENVENIDOS A NUESTRO SISTEMA DE AFORO EN TIEMPO REAL.</p>
        </div>
      </div>
      <div className="login-screen-right">
        <div className="role-box">
          <h3>SELECCIONE CÓMO DESEA INGRESAR</h3>
          <button onClick={handleUser}>USUARIO</button>
          <button onClick={handleAdmin}>ADMINISTRADOR</button>
        </div>

        {/* Agregar el botón "PROBAR MODELO" directamente aquí */}
        <div className="test-button-container">
          <button className="super-button" onClick={handleProbarModelo}>
            <span>PROBAR MODELO</span>
            <svg fill="none" viewBox="0 0 24 24" className="arrow">
              <path
                strokeLinejoin="round"
                strokeLinecap="round"
                strokeWidth={2}
                stroke="currentColor"
                d="M5 12h14M13 6l6 6-6 6"
              />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
}
